<script setup lang="ts">
import {ref,computed,watch,onMounted} from 'vue';import {useRoute,useRouter,RouterLink} from 'vue-router';import {db} from '../lib/supabase';import {list,slugify,imageUrl,uploadImage,money,tables} from '../lib/catalog';
const route=useRoute(),router=useRouter();const sections=[{path:'',title:'Visão geral',table:''},{path:'produtos',title:'Produtos',table:'digital_catalog_products'},{path:'categorias',title:'Categorias',table:'digital_catalog_categories'},{path:'banners',title:'Banners',table:'digital_catalog_banners'},{path:'destaques',title:'Destaques',table:'digital_catalog_products'},{path:'configuracoes',title:'Configurações',table:'digital_catalog_settings'},{path:'fretes',title:'Fretes',table:'fretes_cidades'},{path:'black-friday',title:'Black Friday',table:'black_friday_promos'},{path:'pedidos',title:'Pedidos',table:'pedidos'},{path:'pagamentos',title:'Pagamentos',table:'pagamentos'}];
const active=computed(()=>sections.find(s=>s.path===(route.params.section||''))||sections[0]);const records=ref<Record<string,any>[]>([]),loading=ref(false),error=ref(''),notice=ref(''),search=ref(''),editing=ref<Record<string,any>|null>(null),draft=ref<Record<string,any>>({}),uploading=ref(false);const sectionFields:Record<string,string[]>={
'digital_catalog_products':['nome','slug','descricao','categoria','categoria_id','preco','preco_promocional','imagem_url','imagem_2_url','imagem_3_url','ativo','destaque','instagram_destaque','ordem'],
'digital_catalog_categories':['nome','slug','imagem_url','ativo','ordem'],
'digital_catalog_banners':['titulo','subtitulo','imagem_desktop','imagem_mobile','link','texto_botao','ativo','ordem'],
'digital_catalog_settings':['nome_empresa','nome_equipe','whatsapp_vendas','instagram','logo_url','texto_topo','texto_secundario','texto_whatsapp','entrega_expressa','ativo'],
'fretes_cidades':['cidade','custo','custo_expresso','estrategia','status'],
'black_friday_promos':['produto','preco_promocional','data_inicio','data_fim','ativo','quantidade','vendidos','destaque'],
'pedidos':['codigo','cliente_nome','cliente_email','cliente_telefone','subtotal','frete','total','cidade','endereco','periodo_entrega','cartinha','origem','status'],
'pagamentos':['pedido_id','mercado_pago_payment_id','status','valor']};
const fields=computed(()=>sectionFields[active.value.table]||[]);const filtered=computed(()=>records.value.filter(r=>JSON.stringify(r).toLowerCase().includes(search.value.toLowerCase())&&(active.value.path!=='destaques'||r.destaque)));
const readonly=computed(()=>['pedidos','pagamentos'].includes(active.value.table));
async function load(){editing.value=null;records.value=[];error.value='';notice.value='';if(!active.value.table)return;loading.value=true;try{records.value=await list<Record<string,any>>(active.value.table,false);}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{loading.value=false;}}
watch(()=>route.params.section,load);onMounted(load);
function newRecord(){const defaults:Record<string,unknown>={ativo:true,ordem:0,preco:0,destaque:false,instagram_destaque:false,status:'ativo',entrega_expressa:false};draft.value=Object.fromEntries(fields.value.map(f=>[f,defaults[f]??(f==='categoria_id'||f==='produto'?'':f.includes('preco')||f==='custo'||f==='quantidade'||f==='vendidos'?0:f==='ativo'||f==='destaque'||f==='instagram_destaque'||f==='entrega_expressa'?false:'')]));editing.value={};}
function edit(r:Record<string,any>){draft.value=Object.fromEntries(fields.value.map(f=>[f,r[f]??'']));editing.value=r;}
function isCheck(f:string){return ['ativo','destaque','instagram_destaque','entrega_expressa'].includes(f)}function isNumber(f:string){return ['preco','preco_promocional','ordem','custo','custo_expresso','quantidade','vendidos','subtotal','frete','total','valor'].includes(f)}function isImage(f:string){return f.startsWith('imagem_')||f==='logo_url'}
async function imageUpload(event:Event,f:string){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;uploading.value=true;error.value='';try{draft.value[f]=await uploadImage(file);}catch(e){error.value=String(e)}finally{uploading.value=false;}}
async function save(){if(readonly.value)return;error.value='';try{const data={...draft.value};if(data.nome&&!data.slug)data.slug=slugify(data.nome);for(const f of fields.value){if(isNumber(f))data[f]=data[f]===''?null:Number(data[f]);if((f==='categoria_id'||f==='produto')&&!data[f])data[f]=null;}const q=editing.value?.id?db().from(active.value.table).update(data).eq('id',editing.value.id):db().from(active.value.table).insert(data);const {error:e}=await q;if(e)throw e;notice.value='Registro salvo com sucesso.';await load();notice.value='Registro salvo com sucesso.';}catch(e){error.value=e instanceof Error?e.message:String(e);}}
async function remove(r:Record<string,any>){if(readonly.value||!confirm('Excluir este registro definitivamente?'))return;try{const{error:e}=await db().from(active.value.table).delete().eq('id',r.id);if(e)throw e;await load();notice.value='Registro excluído.';}catch(e){error.value=String(e);}}
async function toggle(r:Record<string,any>,field:string){try{const {error:e}=await db().from(active.value.table).update({[field]:!r[field]}).eq('id',r.id);if(e)throw e;r[field]=!r[field];}catch(e){error.value=String(e);}}
async function logout(){await db().auth.signOut();router.push('/admin/catalogo/login');}
</script>
<template><div class="admin-layout"><aside class="sidebar"><RouterLink class="side-brand" to="/">✿ Shopping de Flores</RouterLink><div class="small-side">GERENCIAMENTO</div><RouterLink v-for="s in sections" :key="s.title" :to="`/admin/catalogo${s.path?'/'+s.path:''}`" :class="['side-link',{selected:active.path===s.path}]">{{s.title}}</RouterLink><div class="sidebar-bottom"><RouterLink to="/">Ver catálogo ↗</RouterLink><button @click="logout">Sair da conta</button></div></aside><main class="admin-main"><header class="admin-top"><span>CATÁLOGO DIGITAL / ADMINISTRAÇÃO</span><span>Supabase conectado</span></header><section class="admin-body"><div class="eyebrow">SHOPPING DE FLORES</div><div class="admin-title"><div><h1>{{active.title}}</h1><p>Gerencie os dados do catálogo digital diretamente no Supabase.</p></div><button v-if="active.table&&!readonly" class="btn primary" @click="newRecord">+ Novo registro</button></div><p v-if="error" class="notice error">{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><template v-if="!active.table"><div class="stats"><div v-for="s in sections.filter(s=>s.table)" :key="s.title" class="stat"><h3>{{s.title}}</h3><RouterLink :to="`/admin/catalogo/${s.path}`">Abrir módulo ↗</RouterLink></div></div><p class="notice">A tela administrativa usa autenticação Supabase e permissões RLS. As integrações de pagamento devem continuar no servidor.</p></template><template v-else><div class="filters"><input v-model="search" placeholder="Buscar registros..." aria-label="Buscar registros"/><span>{{filtered.length}} registro(s)</span></div><p v-if="loading" class="notice">Carregando...</p><div v-else class="admin-rows"><div v-for="r in filtered" :key="r.id" class="admin-row"><img v-if="r.imagem_url" :src="imageUrl(r.imagem_url)" alt=""/><div class="admin-row-text"><strong>{{r.nome||r.titulo||r.cidade||r.codigo||r.nome_empresa||r.mercado_pago_payment_id||r.id}}</strong><small>{{r.categoria||r.slug||r.status||r.cliente_nome||''}}</small><span v-if="r.preco!=null">{{money(r.preco)}}</span><span v-if="r.total!=null">{{money(r.total)}}</span></div><div class="admin-actions"><button v-if="r.ativo!==undefined&&!readonly" @click="toggle(r,'ativo')">{{r.ativo?'Ativo ✓':'Inativo'}}</button><button v-if="r.destaque!==undefined&&!readonly" @click="toggle(r,'destaque')">{{r.destaque?'★ Destaque':'☆ Destaque'}}</button><button @click="edit(r)">{{readonly?'Visualizar':'Editar'}}</button><button v-if="!readonly" @click="remove(r)">Excluir</button></div></div><p v-if="!filtered.length" class="notice">Nenhum registro encontrado.</p></div></template></section></main></div>
<div v-if="editing!==null" class="backdrop" @click.self="editing=null"><aside class="editor"><div class="cart-heading"><h2>{{editing.id?'Editar registro':'Novo registro'}}</h2><button @click="editing=null">✕</button></div><form @submit.prevent="save"><label v-for="f in fields" :key="f" class="field"><span>{{f.replaceAll('_',' ')}}</span><input v-if="isCheck(f)" type="checkbox" v-model="draft[f]" :disabled="readonly"/><select v-else-if="f==='estrategia'" v-model="draft[f]" :disabled="readonly"><option value="cobrar_valor">Cobrar valor</option><option value="gratis">Grátis</option><option value="invisivel_gratis">Invisível grátis</option></select><select v-else-if="f==='status'&&active.table==='fretes_cidades'" v-model="draft[f]"><option value="ativo">Ativo</option><option value="inativo">Inativo</option></select><textarea v-else-if="['descricao','texto_topo','texto_secundario','texto_whatsapp','cartinha','endereco'].includes(f)" v-model="draft[f]" :disabled="readonly" rows="3"/><input v-else :type="isNumber(f)?'number':f.startsWith('data_')?'datetime-local':'text'" :step="isNumber(f)?'0.01':undefined" v-model="draft[f]" :disabled="readonly"/><img v-if="isImage(f)&&draft[f]" class="editor-preview" :src="imageUrl(draft[f])" alt="Imagem"/><input v-if="isImage(f)&&!readonly" type="file" accept="image/png,image/jpeg,image/webp" @change="imageUpload($event,f)"/></label><button v-if="!readonly" type="submit" class="btn primary full" :disabled="uploading">{{uploading?'Enviando imagem...':'Salvar alterações'}}</button></form></aside></div>
</template>